head.script:
scwin.screenId = "jldfil25200";

///////// 1. 변수 및 선언 영역 /////////

scwin.isBeforePW = true;

scwin.delay = false;


///////// 2. 초기화 영역 /////////

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_isurCd", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("isurCd")))); } },
        { childId: "ipt_fssUnqNo", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("fssUnqNo")))); } },
        { childId: "ipt_comNm", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("comNm")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.checkResult();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25200.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.delay = undefined; scwin.result = undefined;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25200.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Save_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Save_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.save()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25200.btn_Save_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Save = async function () {
    const sbmOptions = {
        id: "tx_fn_Save",
        method: "post",
        action: "/account/password.do?method=updatePassword",
        ref: "dma_SaveReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil25200.tx_fn_Save" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_checkIsBeforePW
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_checkIsBeforePW = async function () {
    const sbmOptions = {
        id: "tx_checkIsBeforePW",
        method: "post",
        action: "/main/login.do?method=isBeforePw",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil25200.tx_checkIsBeforePW" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_checkSafety
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_checkSafety = async function () {
    const sbmOptions = {
        id: "tx_checkSafety",
        method: "post",
        action: "/common/checkSafety.do?method=checkPWSafety",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil25200.tx_checkSafety" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.checkResult
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkResult = async function () {
    /* sdd-asis-lifecycle:begin checkResult — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const tp = (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sType" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sType"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sType" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sType")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sType" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sType"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sType" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sType")))));
    if (tp === '1') {
        await $c.win.alert('비밀번호 수정을 완료하였습니다.');
    } else {
        if (tp === '2') {
            await $c.win.alert((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sMessage" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sMessage"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sMessage" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sMessage")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sMessage" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sMessage"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "sMessage" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("sMessage"))))));
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.save = async function () {
    /* sdd-asis-lifecycle:begin fn_Save — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.passwordForm || { elements: [] });
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_pwChgConfrmVal'))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_pw'))) {
        return;
    }
    if ($c.cm.fn_NullChk($c.util.getComponent('ipt_pwChk'))) {
        return;
    }
    if ($c.util.getComponent('ipt_pw').getValue()!== $c.util.getComponent('ipt_pwChk').getValue()) {
        await $c.win.alert('입력한 새 비밀번호가 일치하지 않습니다. 새 비밀번호를 확인하십시오.');
        return;
    }
    if (!await scwin.checkPassword($c.util.getComponent('ipt_pw').getValue())) {
        pw.focus();
        return;
    }
    if ($c.util.getComponent('ipt_isPass').getValue() !== "Y") {
        await $c.win.alert("보안등급이 낮습니다. 비밀번호를 다시 입력해주십시오.");
        return;
    }
    if ($c.util.getComponent('dma_SaveReq').get('pwInitYn')=== 'Y') {
        $c.util.getComponent('dma_SaveReq').get('pwInitYn')=== 'N';
    }
    frm.action = '/account/password.do?method=updatePassword';
    await scwin.tx_fn_Save();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkPassword
 * @author Inswave
 * @date 2026. 09. 29
 * @param _password
 * @returns
 * @hidden N
*/
scwin.checkPassword = async function (_password) {
    /* sdd-asis-lifecycle:begin fn_CheckPassword — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const pwVal = _password;
    if (pwVal.length < 9) {
        await $c.win.alert("변경 비밀번호를 9자 이상 입력하셔야 합니다.");
        return false;
    }
    const strChk = /^[\a-z0-9_!@#^&*()]{8,}$/;
    if (!(strChk.test(pwVal.toLowerCase()))) {
        await $c.win.alert("변경 비밀번호는 한글,띄어쓰기는 사용하실 수 없습니다.\n_!@#^&*() 이외의 특수문자는 사용하실 수 없습니다.");
        return false;
    }
    const alpha_t = "abcdefghijklmnopqrstuvwxyz";
    const sChar_t = "_!@#^&*()";
    const number_t = "1234567890";
    let sChar_Count_t = 0;
    let alphaCheck_t = false;
    let numberCheck_t = false;
    for (var i = 0; i < pwVal.length; i++) {
        if (sChar_t.indexOf(pwVal.charAt(i)) != -1) {
            sChar_Count_t++;
        }
        if (alpha_t.indexOf(pwVal.charAt(i)) != -1) {
            alphaCheck_t = true;
        }
        if (number_t.indexOf(pwVal.charAt(i)) != -1) {
            numberCheck_t = true;
        }
    }
    if (sChar_Count_t < 1 || alphaCheck_t !== true || numberCheck_t !== true) {
        await $c.win.alert("변경 비밀번호는 영문, 숫자, 특수문자의 조합이어야 합니다.");
        return false;
    }
    let sameCount = 1;
    let isCont = true;
    for (var i = 0; i < pwVal.length - 1; i++) {
        const currentChar = pwVal.charAt(i);
        const nextChar = pwVal.charAt(i + 1);
        const currentCharNum = parseInt(currentChar.charCodeAt(0));
        const continueCharNum = parseInt(nextChar.charCodeAt(0));
        if (currentChar === nextChar) {
            sameCount = sameCount + 1;
            if (sameCount >= 3) {
                break;
            }
        } else {
            sameCount = 1;
        }
        if (!(isCont && currentCharNum === continueCharNum - 1)) {
            isCont = false;
        }
    }
    if (sameCount >= 3) {
        await $c.win.alert('동일한 문자 또는 숫자가 3자 이상로 구성된 비밀번호는 사용하실 수 없습니다.');
        return false;
    }
    if (isCont) {
        await $c.win.alert('주기성 문자(abcd, 1234 등)로 구성된 비밀번호는 사용하실 수 없습니다.');
        return false;
    }
    const charChk = /^[\a-z]{8,}$/;
    const numChk = /^[\d]{8,}$/;
    if (charChk.test(pwVal) || numChk.test(pwVal)) {
        await $c.win.alert('변경 비밀번호는 영문, 숫자, 특수문자의 조합이어야 합니다.');
        return false;
    }
    const keyboardWord = ["qwertyuiop", "poiuytrewq", "asdfghjkl", "lkjhgfdsa", "zxcvbnm", "mnbvcxz"];
    for (var i = 0; i < keyboardWord.length; i++) {
        for (let j = 0; j < keyboardWord[i].length; j++) {
            if (keyboardWord[i].substring(j, j + 4).length == 4) {
                if (!(pwVal.toLowerCase().indexOf(keyboardWord[i].substring(j, j + 4)) < 0)) {
                    await $c.win.alert('키보드상의 연속된 배열(' + keyboardWord[i].substring(j, j + 4) + ')로 구성된 변경 비밀번호는 사용하실 수 없습니다.');
                    return false;
                }
            }
        }
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDelayKeyup
 * @author Inswave
 * @date 2026. 09. 29
 * @param newPw
 * @returns
 * @hidden N
*/
scwin.fnDelayKeyup = async function (newPw) {
    /* sdd-asis-lifecycle:begin fnDelayKeyup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (newPw.length > 0) {
        if (await scwin.checkPassword(newPw)) {
            if (!scwin.delay) {
                scwin.delay = true;
                self.setTimeout(function() {
                        scwin.checkIsBeforePW();
                    }, 1000);
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
scwin.checkIsBeforePW = scwin.tx_checkIsBeforePW;

/**
 * @method
 * @name scwin.checkSafety_done
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.checkSafety_done = function (data) {
    /* sdd-asis-lifecycle:begin checkSafety_done — as-is 원문 본문(전환 이관 · 포팅 적용됨) */scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_isPass').setValue(scwin.result.isPass);
    $c.util.getComponent('ipt_selfLevel').setValue(scwin.result.selfLevel);
    $c.util.getComponent('txt_msgLevel').setLabel(scwin.result.msgLevel);
    if (scwin.result.msgInfomation !== "") {
        $c.util.getComponent('txt_msgInfomation').setLabel("");
        $("#txt_msgInfomation").append(scwin.result.msgInfomation);
    } else {
        $c.util.getComponent('txt_msgInfomation').setLabel("");
    }
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.checkSafety
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkSafety = async function () {
    const r = await scwin.tx_checkSafety();
    try {
        scwin.checkSafety_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil25200.checkSafety' });
    }
    return r;
};
